  invite.hash=new URLSearchParams({invito:connection.code}).toString();
  try{
   if(navigator.share)await navigator.share({title:'DaFragu English',url:invite.href});
   else {await navigator.clipboard.writeText(invite.href);notify('Link privato copiato.')}
  }catch(error){if(!(error instanceof DOMException && error.name==='AbortError'))notify('Condivisione non riuscita. Riprova.')}
