  history.replaceState(history.state,'',window.location.pathname+window.location.search);
  const current=getConnection();
  if(current.url && (current.url!==sharedEndpoint || current.code!==code)){
   notify('Questo dispositivo è già collegato a un altro spazio.');return;
  }
  if(!/^[a-f0-9]{64}$/.test(code)){notify('Invito non valido. Chiedi un nuovo link.');return}
