 const days=new Set(mine.filter(e=>['complete','practice','answer'].includes(e.kind)).map(e=>day(e.at)));let streak=0;const date=new Date();if(!days.has(day(date.toISOString())))date.setDate(date.getDate()-1);while(days.has(day(date.toISOString()))){streak++;date.setDate(date.getDate()-1)}
