 async function importData(f?:File){if(!f)return;try{if(f.size>2000000)throw Error();const d=JSON.parse(await f.text());if(d.format!=='dafragu-english'||!Array.isArray(d.events)||d.events.length>10000)throw Error();if(d.events.some((e:any)=>typeof e.id!=='string'||!/^[a-zA-Z0-9-]{8,80}$/.test(e.id)||typeof e.profile!=='string'||!validProfile(e.profile)||!['answer','complete','assessment','favorite','practice','goal','profile','challenge','challenge-reply','pin','hide'].includes(e.kind)||!e.data||typeof e.data!=='object'||JSON.stringify(e.data).length>4000||!Number.isFinite(Date.parse(e.at))))throw Error();const ids=new Set(eventsRef.current.map(e=>e.id));const fresh=d.events.filter((e:Event)=>!ids.has(e.id));eventsRef.current=merge(eventsRef.current,fresh);pendingRef.current=merge(pendingRef.current,fresh);setEvents([...eventsRef.current]);setPending([...pendingRef.current]);void synchronize();notify('Progressi importati. Nessun dato esistente è stato cancellato.')}catch{notify('File non valido. Scegli un backup DaFragu English.')}if(file.current)file.current.value=''}
 const phraseList=lessons.flatMap(l=>l.phrases.map((p,i)=>({l,p,key:l.id+'-'+i}))).filter(({l,p,key})=>(filter==='Tutte'||filter==='Preferite'&&favorites.has(key)||filter===l.category)&&(!query||normal(p.join(' ')).includes(normal(query))));
