 {tab==='speak'&&<><PageHeading eyebrow="DALLA TESTA ALLA VOCE" title="Let’s talk, davvero." text="Una domanda concreta. La vostra risposta. Nessuna fretta di essere perfetti."/><div className="segmented"><button className={!pair?'selected':''} onClick={()=>setPair(false)}><Mic size={17}/> Mi alleno</button><button className={pair?'selected':''} onClick={()=>setPair(true)}><Users size={17}/> In coppia</button></div>{!pair?<><label className="field-label" htmlFor="situation">Scegli una situazione</label><select id="situation" value={activeLesson.id} onChange={e=>setSpeaking(e.target.value)}>{lessons.map(l=><option key={l.id} value={l.id}>{l.title} · {l.en}</option>)}</select><div className="practice-card"><VoicePractice key={activeLesson.id} prompt={activeLesson.speak} model={activeLesson.speakModel} accent={accent} slow={slow} onPractice={()=>add('practice',{lesson:activeLesson.id})}/></div></>:<div className="pair-card"><div className="pair-pick"><label className="field-label">Primo profilo<select value={pa} onChange={e=>{setPairA(e.target.value);if(e.target.value===pb)setPairB('')}}>{profiles.map(p=><option key={p} value={p}>{p}</option>)}</select></label><label className="field-label">Con chi<select value={pb} onChange={e=>setPairB(e.target.value)}>{profiles.filter(p=>p!==pa).map(p=><option key={p} value={p}>{p}</option>)}</select></label></div><div className="pair-avatars"><span>{pa[0]}</span><span>{pb[0]}</span></div><span className="eyebrow">MISSIONE DI COPPIA · {pairTurn+1} / 4</span><h2>{['Alla reception','Al ristorante','In giro per la città','Un piccolo imprevisto'][pairTurn]}</h2><p><b>{pairTurn%2===0?pa:pb}</b> fa {['la receptionist','il cameriere','la persona del posto','l’addetto dell’hotel'][pairTurn]}. <b>{pairTurn%2===0?pb:pa}</b> risponde in inglese.</p><div className="pair-prompt"><span>CHI INIZIA DICE:</span><p lang="en">{['Hello! Do you have a reservation?','Are you ready to order?','Where would you like to go?','What’s the problem with your room?'][pairTurn]}</p><AudioButton text={['Hello! Do you have a reservation?','Are you ready to order?','Where would you like to go?','What’s the problem with your room?'][pairTurn]} slow={slow} accent={accent} label="Ascolta la domanda"/></div><button className="text-button" onClick={()=>setPairShow(!pairShow)}>{pairShow?'Nascondi':'Serve'} un suggerimento?<ChevronRight size={15}/></button>{pairShow&&<p className="model" lang="en">{['Yes, we have a reservation under the name Del Cielo. Is breakfast included?','Yes, I’d like the grilled fish, please. Could we have some still water?','We’d like to go to the station. Is it within walking distance?','The air conditioning isn’t working. Could we change rooms, please?'][pairTurn]}</p>}<p className="small muted">Provate a continuare lo scambio con una domanda in più. Questa attività è libera e non assegna punteggi.</p><button className="primary" onClick={()=>{setPairTurn((pairTurn+1)%4);setPairShow(false)}}>{pairTurn===3?'Ricomincia la missione':'Scambiatevi i ruoli'}<ArrowRight size={18}/></button></div>}</>}
 {tab==='phrases'&&<><PageHeading eyebrow="IL VOSTRO FRASARIO" title="Le parole, a portata di mano." text="Cercate una frase, ascoltatela e salvate quelle che volete ricordare."/><div className="search-field"><Search size={20}/><input aria-label="Cerca nel frasario" placeholder="Cerca in italiano o inglese…" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button aria-label="Cancella ricerca" onClick={()=>setQuery('')}><X size={18}/></button>}</div><div className="chips">{['Tutte','Preferite','Fondamenta','In viaggio','Vita quotidiana','Conversazione','Imprevisti'].map(c=><button key={c} className={filter===c?'selected':''} onClick={()=>setFilter(c)}>{c==='Preferite'&&<Bookmark size={14}/>} {c}</button>)}</div><div className="phrase-count">{phraseList.length} {phraseList.length===1?'espressione':'espressioni'} {filter==='Preferite'?(phraseList.length===1?'salvata':'salvate'):(phraseList.length===1?'utile':'utili')}</div><div className="phrases-list">{phraseList.map(({l,p,key})=><article key={key} className="phrase-card"><div className="phrase-main"><small>{l.en}</small><h3 lang="en">{p[0]}</h3><p>{p[1]}</p></div><div className="phrase-actions"><AudioButton text={p[0]} slow={slow} accent={accent}/><button className={'icon-button '+(favorites.has(key)?'bookmarked':'')} onClick={()=>add('favorite',{key,value:!favorites.has(key)})} aria-label={favorites.has(key)?'Rimuovi dai preferiti':'Salva nei preferiti'} aria-pressed={favorites.has(key)}><Bookmark size={19} fill={favorites.has(key)?'currentColor':'none'}/></button></div></article>)}</div>{!phraseList.length&&<Empty icon={Bookmark} title="Qui c’è spazio per le vostre frasi." text={filter==='Preferite'?'Tocca il segnalibro accanto a una frase per ritrovarla qui.':'Nessuna frase trovata. Prova una parola diversa.'}/>}</>}
